//! Sprite coordinates of Winamp 2.x classic skins. Generated; do not edit by hand.
//!
//! Transcribed from Webamp's `skinSprites.ts` (MIT, Copyright (c) 2015 Jordan Eldredge),
//! commit 999f5676143c5696af69e1b27db901f2d35f428b. `gen.bmp` sprites are left out.

use crate::image::Rect;

/// A bitmap file of a classic skin.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Sheet {
    Main,
    Cbuttons,
    Titlebar,
    Numbers,
    NumsEx,
    Text,
    Posbar,
    Volume,
    Balance,
    Monoster,
    Playpaus,
    Shufrep,
    Eqmain,
    EqEx,
    Pledit,
}

impl Sheet {
    pub const ALL: [Sheet; 15] = [
        Sheet::Main,
        Sheet::Cbuttons,
        Sheet::Titlebar,
        Sheet::Numbers,
        Sheet::NumsEx,
        Sheet::Text,
        Sheet::Posbar,
        Sheet::Volume,
        Sheet::Balance,
        Sheet::Monoster,
        Sheet::Playpaus,
        Sheet::Shufrep,
        Sheet::Eqmain,
        Sheet::EqEx,
        Sheet::Pledit,
    ];

    /// File name without extension, lower case (`.bmp` or `.png` in the skin).
    pub fn stem(self) -> &'static str {
        match self {
            Sheet::Main => "main",
            Sheet::Cbuttons => "cbuttons",
            Sheet::Titlebar => "titlebar",
            Sheet::Numbers => "numbers",
            Sheet::NumsEx => "nums_ex",
            Sheet::Text => "text",
            Sheet::Posbar => "posbar",
            Sheet::Volume => "volume",
            Sheet::Balance => "balance",
            Sheet::Monoster => "monoster",
            Sheet::Playpaus => "playpaus",
            Sheet::Shufrep => "shufrep",
            Sheet::Eqmain => "eqmain",
            Sheet::EqEx => "eq_ex",
            Sheet::Pledit => "pledit",
        }
    }

    /// Size that covers every sprite on the sheet. Smaller sheets are padded to it.
    pub fn size(self) -> (u32, u32) {
        match self {
            Sheet::Main => (275, 116),
            Sheet::Cbuttons => (136, 36),
            Sheet::Titlebar => (344, 86),
            Sheet::Numbers => (90, 13),
            Sheet::NumsEx => (108, 13),
            Sheet::Text => (155, 18),
            Sheet::Posbar => (307, 10),
            Sheet::Volume => (68, 433),
            Sheet::Balance => (47, 433),
            Sheet::Monoster => (56, 24),
            Sheet::Playpaus => (48, 9),
            Sheet::Shufrep => (92, 85),
            Sheet::Eqmain => (275, 315),
            Sheet::EqEx => (275, 56),
            Sheet::Pledit => (280, 186),
        }
    }
}

